import{_ as o,c as r,o as t,ag as a}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"瀏覽器與嗅探器","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/browser.md","filePath":"zh-TW/guide/browser.md","lastUpdated":1791311600000}'),l={name:"zh-TW/guide/browser.md"};function d(i,e,c,n,s,g){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="瀏覽器與嗅探器" tabindex="-1">瀏覽器與嗅探器 <a class="header-anchor" href="#瀏覽器與嗅探器" aria-label="Permalink to &quot;瀏覽器與嗅探器&quot;">​</a></h1><p>nPlyr 內建一個基於 <code>WKWebView</code> 的真正的<strong>多分頁瀏覽器</strong>，並帶有<strong>媒體嗅探器</strong>。當你遇到一個不主動提供直鏈的頁面時，它就是用來擷取直鏈的工具。</p><h2 id="瀏覽器" tabindex="-1">瀏覽器 <a class="header-anchor" href="#瀏覽器" aria-label="Permalink to &quot;瀏覽器&quot;">​</a></h2><p>這是一個 Chrome 風格的分頁瀏覽器：</p><ul><li><strong>分頁</strong>——新建 / 關閉 / 切換 / 重新排序；將分頁拖出可成為獨立視窗（macOS）。</li><li><strong>導覽</strong>——上一頁、下一頁、重新載入，以及帶自動完成的網址列。</li><li><strong>鍵盤快捷鍵</strong>——<code>⌘T</code> 新建分頁、<code>⌘R</code> 重新載入、<code>⌘[</code> / <code>⌘]</code> 上一頁 / 下一頁、<code>⌘L</code> 聚焦網址列。</li><li><strong>拖放</strong>——將 URL 或文字拖入視窗即可開啟。</li><li><strong>彈出視窗</strong>——<code>target=&quot;_blank&quot;</code> 與 <code>window.open</code> 會在新分頁中開啟，而不是被攔截。</li><li><strong>對話框</strong>——JS 的 <code>alert</code> / <code>confirm</code> / <code>prompt</code> 以原生方式呈現。</li><li><strong>下載</strong>——被攔截的下載連結會在應用程式內<strong>下載</strong>分頁（<code>nplyr://downloads</code>）中開啟。</li></ul><h2 id="嗅探器的運作原理" tabindex="-1">嗅探器的運作原理 <a class="header-anchor" href="#嗅探器的運作原理" aria-label="Permalink to &quot;嗅探器的運作原理&quot;">​</a></h2><p>頁面載入時，nPlyr 會注入一個腳本，攔截：</p><ul><li><code>fetch</code> 與 <code>XMLHttpRequest</code>，</li><li><code>video.src</code> 與 <code>HTMLMediaElement</code> 播放，</li><li><code>MediaSource</code> / <code>SourceBuffer.appendBuffer</code>。</li></ul><p>它還會透過 <code>WKNavigationDelegate</code> 監視導覽，以捕獲服務端媒體重新導向。任何看起來像媒體檔案的內容——<strong>m3u8 / mp4 / flv / ts</strong>——都會連同其<strong>請求標頭</strong>（referer、user-agent、cookie、auth）一起被收集到結果抽屜中。</p><p>在抽屜中你可以：</p><ul><li>立即在<a href="/zh-TW/guide/player.html">播放器</a>中<strong>播放</strong>該連結。</li><li>透過<a href="/zh-TW/guide/downloads.html">下載</a>將其<strong>下載</strong>（保留請求標頭）。</li><li><strong>複製</strong> URL 與請求標頭，以便在其他地方使用。</li></ul><blockquote><p>嗅探器只擷取頁面實際請求的連結。使用專有播放器或重度 DRM 包裹影片串流的網站可能不會暴露乾淨的直鏈——對於這類來源，一個了解該來源 API 的<a href="/zh-TW/guide/miniapps.html">小程式</a>是更可靠的路徑。</p></blockquote><h2 id="已知限制" tabindex="-1">已知限制 <a class="header-anchor" href="#已知限制" aria-label="Permalink to &quot;已知限制&quot;">​</a></h2><p>以下項目是有意降低優先級，可能在後續版本中提供：</p><ul><li>頁內右鍵選單項目（「在新分頁開啟連結」、「下載連結」）——macOS 的 <code>WKUIDelegate</code> 右鍵選單鉤子是 iOS 專屬的；nPlyr 目前依賴分頁列與工具列。</li><li>頁內<strong>尋找</strong>（<code>⌘F</code>）——WebKit API 存在，但 UI 尚未接好。</li><li><strong>列印</strong>（<code>⌘P</code>）——WebKit 支援，但尚無選單項目。</li><li><code>⌘W</code> 在多個分頁開啟時會關閉整個視窗；按分頁關閉正在規劃中。</li><li>全面重啟應用程式後，已開啟的分頁與歷史<strong>不會</strong>恢復。</li></ul><h2 id="隱私" tabindex="-1">隱私 <a class="header-anchor" href="#隱私" aria-label="Permalink to &quot;隱私&quot;">​</a></h2><p>該瀏覽器是一個標準的 <code>WKWebView</code>。它不會注入自身的追蹤器。Cookie 與本機儲存都留在應用程式的容器中。完整說明請參閱<a href="/zh-TW/guide/privacy.html">隱私</a>。</p>',17)])])}const p=o(l,[["render",d]]);export{u as __pageData,p as default};
